"""Small lifecycle integration for the existing graph and checkpoint state."""

from __future__ import annotations

import json
from typing import Any

from codepilot.graph.deps import Deps
from codepilot.graph.evidence import failure_summary, verification_view
from codepilot.observability.lifecycle import snapshot_hash
from codepilot.rsi import archive_root, load_selection, read_json, retrieve, snapshot_sources
from codepilot.schemas.state import RepairState


class SnapshotIdentityError(ValueError):
    """A resumed task must never silently switch its fixed policy."""


def begin(state: RepairState, deps: Deps, stage: str) -> RepairState:
    try:
        return _begin(state, deps, stage)
    except SnapshotIdentityError as exc:
        deps.lifecycle.emit("initialization_failed", category="identity", error=str(exc))
        if stage != "finalize":
            raise
        # Finalize must still preserve the original failure, patch and usage.
        return state
    except Exception as exc:
        deps.lifecycle.emit(
            "initialization_failed", category="optional", error=str(exc), fallback="existing_node"
        )
        return state


def _begin(state: RepairState, deps: Deps, stage: str) -> RepairState:
    policy = state.policy_snapshot
    if not deps.harness_started:
        if policy:
            try:
                snapshot = read_json(deps.artifacts.run_dir / "harness/snapshot.json")
            except (OSError, ValueError) as exc:
                raise SnapshotIdentityError(
                    "fixed snapshot unavailable; preserve recovery scene"
                ) from exc
            if snapshot.get("state_schema_version", 1) != 1:
                raise SnapshotIdentityError("snapshot state schema is incompatible")
            if snapshot_hash(snapshot) != policy.get("sha256"):
                raise SnapshotIdentityError(
                    "fixed policy snapshot identity mismatch; refusing in-flight switch"
                )
        else:
            try:
                selection = load_selection()
            except (OSError, ValueError, KeyError) as exc:
                deps.lifecycle.emit("policy_load_failed", error=str(exc), fallback="builtin")
                selection = {
                    "schema_version": 1,
                    "version": "builtin-phase26-v1",
                    "status": "pending",
                    "instruction": "",
                    "experiences": [],
                }
            try:
                sources = snapshot_sources()
            except OSError as exc:
                deps.lifecycle.emit("source_snapshot_unavailable", error=str(exc))
                sources = {}
            snapshot = {
                "selection": selection,
                "selection_source": str(archive_root()),
                "sources": sources,
                "plugins": deps.lifecycle.versions(),
                "configuration": {
                    "environment": deps.env_spec.model_dump(mode="json"),
                    "budget": state.budget.model_dump(mode="json"),
                    "repository": deps.repository,
                    "base_commit": state.base_commit,
                },
                "state_schema_version": 1,
                "prompts": {
                    "coder": selection.get("prompts", {}).get(
                        "coder", getattr(deps.coder, "system_prompt", "")
                    ),
                    "planner": selection.get("prompts", {}).get(
                        "planner", getattr(deps.planner, "system_prompt", "")
                    ),
                    "reviewer": selection.get("prompts", {}).get(
                        "reviewer", getattr(deps.reviewer, "system_prompt", "")
                    ),
                },
            }
            deps.artifacts.write_json("harness/snapshot.json", snapshot)
            policy = {
                "version": selection["version"],
                "sha256": snapshot_hash(snapshot),
                "artifact": "harness/snapshot.json",
                "status": selection.get("status", "pending"),
            }
        selection = snapshot["selection"]
        deps.experience_snapshot = []
        cache = getattr(deps.tools, "query_cache", None)
        if cache is not None:
            counters = state.runtime.get("cache", {})
            cache.hits = int(counters.get("hits", 0))
            cache.misses = int(counters.get("misses", 0))
            if state.events:
                cache.last_invalidation = "worker_restart_no_memory_cache"
        for name, prompt in snapshot.get("prompts", {}).items():
            agent = getattr(deps, name, None)
            if agent is not None and hasattr(agent, "system_prompt"):
                agent.system_prompt = prompt
        deps.coder.experience_feedback = json.dumps(
            {"instruction": selection.get("instruction", ""), "entries": deps.experience_snapshot},
            ensure_ascii=False,
        )
        deps.fixed_selection = selection
        deps.harness_started = True
        deps.lifecycle.bind(
            {"task_id": state.task_id, "stage": stage, "iteration": state.iteration},
            str(policy.get("sha256", "")),
        )
        deps.lifecycle.emit(
            "resume" if state.events else "task_start",
            snapshot=policy,
            reuse="checkpoint-completed nodes, settled responses and identity-valid evidence"
            if state.events
            else "none",
            redo="pending or invalidated stages; no exactly-once guarantee across crash windows"
            if state.events
            else "none",
        )
    if deps.harness_started:
        try:
            audit: list[dict[str, Any]] = []
            deps.experience_snapshot = retrieve(
                deps.fixed_selection,
                deps.repository,
                stage=stage,
                failure_category=state.failure_summary.get("category"),
                environment={
                    "runner": deps.env_spec.test_command,
                    "environment": snapshot_hash(deps.env_spec.model_dump(mode="json")),
                    "version": deps.env_spec.python_version,
                },
                tags=tuple(state.issue_analysis.keywords) if state.issue_analysis else (),
                audit=audit,
            )
            deps.coder.experience_feedback = json.dumps(
                {
                    "instruction": deps.fixed_selection.get("instruction", "")[:1000],
                    "entries": deps.experience_snapshot,
                    "advisory": True,
                },
                ensure_ascii=False,
            )
            deps.lifecycle.emit("experience_selection", decisions=audit)
        except Exception as exc:
            deps.experience_snapshot = []
            deps.coder.experience_feedback = ""
            deps.lifecycle.emit("experience_unavailable", error=str(exc), fallback="no_experience")
    now = deps.clock().isoformat()
    deps.lifecycle.external_wait_seconds = 0.0
    deps.lifecycle.queued_seconds = 0.0
    runtime = {
        **state.runtime,
        "stage": stage,
        "stage_started_at": now,
        "stage_elapsed_seconds": 0.0,
        "activity": "executing",
        "revision": int(state.runtime.get("revision", 0)) + 1,
    }
    deps.lifecycle.bind(
        {
            "task_id": state.task_id,
            "stage": stage,
            "iteration": state.iteration,
            "revision": runtime["revision"],
            "candidate_hash": state.frozen_patch_hash,
        },
        str(policy.get("sha256", "")),
    )
    deps.lifecycle.emit("stage_start", started_at=now, runtime=runtime)
    return state.model_copy(
        update={
            "runtime": runtime,
            "policy_snapshot": policy,
            "experience_refs": [f"{e['id']}@{e['version']}" for e in deps.experience_snapshot],
        }
    )


def complete(
    state: RepairState, update: dict[str, Any], deps: Deps, elapsed: float
) -> dict[str, Any]:
    merged = state.model_copy(update=update)
    runtime = {
        **state.runtime,
        "stage_elapsed_seconds": round(elapsed, 3),
        "activity": "idle",
        "last_completed_at": deps.clock().isoformat(),
    }
    durations = dict(runtime.get("stage_seconds", {}))
    stage = str(runtime.get("stage", "unknown"))
    durations[stage] = round(durations.get(stage, 0) + elapsed, 3)
    runtime["stage_seconds"] = durations
    runtime["external_wait_seconds"] = round(
        float(state.runtime.get("external_wait_seconds", 0)) + deps.lifecycle.external_wait_seconds,
        3,
    )
    runtime["resource_queued_seconds"] = (
        float(state.runtime.get("resource_queued_seconds", 0)) + deps.lifecycle.queued_seconds
    )
    runtime["executing_seconds"] = round(
        float(state.runtime.get("executing_seconds", 0))
        + max(0, elapsed - deps.lifecycle.external_wait_seconds - deps.lifecycle.queued_seconds),
        3,
    )
    cache = getattr(deps.tools, "query_cache", None)
    runtime["has_modification"] = bool(merged.current_patch)
    runtime["event_seq"] = deps.events.last_seq
    runtime["run_id"] = merged.run_id
    runtime["cache"] = {"hits": cache.hits, "misses": cache.misses} if cache else {}
    if merged.current_patch != state.current_patch:
        deps.lifecycle.emit(
            "candidate_changed",
            old=state.frozen_patch_hash,
            new=merged.frozen_patch_hash,
            has_modification=bool(merged.current_patch),
        )
        runtime["last_effective_progress"] = deps.clock().isoformat()
    if stage in {"validate_patch", "run_target_tests", "run_regression"}:
        summary = failure_summary(merged)
        write_projection(deps, f"failures/{stage}-{state.iteration}.json", summary)
        update["failure_summary"] = summary
        deps.lifecycle.emit(
            "after_validation", view=verification_view(merged), failure_summary=summary
        )
        old_evidence = {
            k: v
            for k, v in state.failure_summary.items()
            if k not in {"new_since_last_attempt", "evidence_refs"}
        }
        new_evidence = {
            k: v for k, v in summary.items() if k not in {"new_since_last_attempt", "evidence_refs"}
        }
        if summary and new_evidence != old_evidence:
            runtime["last_effective_progress"] = deps.clock().isoformat()
    if stage == "plan" and merged.plan:
        contract = merged.plan.contract.model_dump(mode="json")
        write_projection(deps, "harness/contract.json", contract)
        deps.lifecycle.emit("contract_ready", contract=contract)
        if state.plan is None or (
            merged.plan.root_cause_hypothesis != state.plan.root_cause_hypothesis
            or merged.plan.evidence != state.plan.evidence
        ):
            runtime["last_effective_progress"] = deps.clock().isoformat()
    for call in update.get("tool_calls", []):
        progress = call.get("result_summary", {}).get("exploration", {})
        if (
            progress.get("new_relevant_evidence")
            or progress.get("hypothesis_changed")
            or progress.get("candidate_changed")
        ):
            runtime["last_effective_progress"] = deps.clock().isoformat()
            runtime["progress_basis"] = "planned_file_overlap_or_stated_hypothesis; heuristic"
    runtime["event_seq"] = deps.events.last_seq + 1
    deps.lifecycle.emit("stage_end", duration_seconds=elapsed, runtime=runtime)
    return {
        **update,
        "runtime": runtime,
        "policy_snapshot": state.policy_snapshot,
        "experience_refs": state.experience_refs,
    }


def write_projection(deps: Deps, path: str, payload: Any) -> bool:
    try:
        deps.artifacts.write_json(path, payload)
        return True
    except Exception as exc:
        deps.lifecycle.emit("projection_error", artifact=path, error=str(exc))
        return False

src/codepilot/observability/lifecycle.py:
"""Ordered read-only observers. Suggestions are committed by the graph executor."""

from __future__ import annotations

import hashlib
import json
import logging
from collections.abc import Mapping
from types import MappingProxyType
from typing import Any, Protocol

from codepilot.observability.events import EventSink, EventType


def freeze(value: Any) -> Any:
    if isinstance(value, dict):
        return MappingProxyType({k: freeze(v) for k, v in value.items()})
    if isinstance(value, list):
        return tuple(freeze(v) for v in value)
    return value


class Observer(Protocol):
    name: str
    version: str

    def observe(
        self, hook: str, state: Mapping[str, Any], facts: Mapping[str, Any]
    ) -> Mapping[str, Any]: ...


class ResourceObserver:
    """Resource classification seam for existing scheduling, not a new scheduler."""

    name = "resource-classification"
    version = "1"

    def observe(
        self, hook: str, state: Mapping[str, Any], facts: Mapping[str, Any]
    ) -> Mapping[str, Any]:
        if hook == "before_model":
            return {"resource": "model", "activity": "external_wait"}
        if hook == "before_tool":
            permission = facts.get("permission")
            resource = (
                "test"
                if permission == "execute"
                else "workspace_write"
                if permission == "write"
                else "query"
            )
            return {"resource": resource, "activity": "executing"}
        if hook == "stage_start":
            stage = str(state.get("stage", ""))
            return {
                "resource": {
                    "retrieve": "index_read",
                    "build_env": "environment",
                    "run_target_tests": "test",
                    "run_regression": "test",
                }.get(stage, "orchestration")
            }
        return {}


class Lifecycle:
    def __init__(self, events: EventSink, observers: tuple[Observer, ...] | None = None) -> None:
        self.events = events
        self.observers = observers if observers is not None else (ResourceObserver(),)
        self.state: Mapping[str, Any] = MappingProxyType({})
        self.policy_hash = ""
        self.external_wait_seconds = 0.0
        self.queued_seconds = 0.0

    def bind(self, state: dict[str, Any], policy_hash: str) -> None:
        self.state = freeze(state)
        self.policy_hash = policy_hash

    def emit(self, hook: str, **facts: Any) -> list[dict[str, Any]]:
        try:
            return self._emit(hook, **facts)
        except Exception:
            logging.getLogger(__name__).exception(
                "optional lifecycle projection unavailable: %s", hook
            )
            return []

    def _emit(self, hook: str, **facts: Any) -> list[dict[str, Any]]:
        if hook == "resource_acquired":
            self.queued_seconds += float(facts.get("queued_seconds", 0.0))
        if hook == "after_model":
            self.external_wait_seconds += float(facts.get("duration_seconds", 0.0))
        suggestions = []
        for observer in self.observers:
            try:
                advice = dict(observer.observe(hook, self.state, freeze(facts)))
                if advice:
                    suggestions.append({"observer": observer.name, **advice})
            except Exception as exc:
                self.events.emit(
                    node=str(self.state.get("stage", "lifecycle")),
                    type=EventType.LIFECYCLE,
                    status="observer_error",
                    hook=hook,
                    observer=observer.name,
                    error=f"{type(exc).__name__}: {exc}",
                )
        self.events.emit(
            node=str(self.state.get("stage", "lifecycle")),
            type=EventType.LIFECYCLE,
            status=hook,
            hook=hook,
            policy_hash=self.policy_hash,
            summary=str(facts.get("feedback") or hook),
            facts=facts,
            suggestions=suggestions,
        )
        return suggestions

    def versions(self) -> dict[str, str]:
        return {observer.name: observer.version for observer in self.observers}


def snapshot_hash(snapshot: dict[str, Any]) -> str:
    return hashlib.sha256(
        json.dumps(snapshot, sort_keys=True, ensure_ascii=False).encode()
    ).hexdigest()

src/codepilot/observability/resources.py:
"""Local-machine execution gates, reusing worker execution paths.

OS locks also coordinate worker processes. Lock files are retained, never used as
ownership/PID claims; the kernel releases ownership on process exit. No service,
model retry, download cancellation or budget change is introduced.
"""

from __future__ import annotations

import errno
import hashlib
import sys
import tempfile
import threading
import time
from collections.abc import Callable, Iterator
from contextlib import contextmanager
from pathlib import Path
from typing import Any, BinaryIO

_guard = threading.Lock()
_locks: dict[str, tuple[Any, int]] = {}
_local = threading.local()


class ResourceCancelledError(RuntimeError):
    """Cancellation before dispatch; no external request or uncertain usage."""


@contextmanager
def resource_slot(
    resource: str,
    *,
    workspace: Path | None = None,
    cancel: Callable[[], bool] | None = None,
    observe: Callable[..., Any] | None = None,
) -> Iterator[None]:
    key = "pressure" if resource in {"test", "heavy"} else resource
    if workspace is not None:
        key = "workspace:" + str(workspace.resolve())
    held: set[str] = getattr(_local, "held", set())
    if key in held:
        yield
        return
    with _guard:
        lock, users = _locks.get(key, (threading.Lock(), 0))
        _locks[key] = (lock, users + 1)
    started = time.monotonic()
    acquired = False
    execution_started = started
    handle: BinaryIO | None = None
    os_acquired = False
    dispatched = False
    try:
        if observe:
            observe("resource_wait", resource=resource)
        while not acquired:
            if cancel and cancel():
                raise ResourceCancelledError(f"cancelled waiting for {resource}; not dispatched")
            acquired = lock.acquire(timeout=0.1)
        if cancel and cancel():
            raise ResourceCancelledError(f"cancelled before {resource} dispatch")
        folder = Path(tempfile.gettempdir()) / "codepilot-resource-locks"
        folder.mkdir(parents=True, exist_ok=True)
        handle = (folder / (hashlib.sha256(key.encode()).hexdigest() + ".lock")).open("a+b")
        if handle.seek(0, 2) == 0:
            handle.write(b"0")
            handle.flush()
        while not os_acquired:
            if cancel and cancel():
                raise ResourceCancelledError(f"cancelled waiting for {resource}; not dispatched")
            os_acquired = _os_lock(handle, acquire=True)
            if not os_acquired:
                time.sleep(0.1)
        execution_started = time.monotonic()
        dispatched = True
        _local.held = held | {key}
        if observe:
            observe(
                "resource_acquired", resource=resource, queued_seconds=execution_started - started
            )
        yield
    finally:
        try:
            if handle is not None:
                handle.close()  # OS ownership is released even after a process exits.
        finally:
            if acquired:
                _local.held = held
                lock.release()
            with _guard:
                _, users = _locks[key]
                if users == 1:
                    del _locks[key]
                else:
                    _locks[key] = (lock, users - 1)
            if observe and dispatched:
                observe(
                    "resource_released",
                    resource=resource,
                    execution_seconds=time.monotonic() - execution_started,
                )


def _os_lock(handle: BinaryIO, *, acquire: bool) -> bool:
    try:
        handle.seek(0)
        if sys.platform == "win32":
            import msvcrt

            msvcrt.locking(handle.fileno(), msvcrt.LK_NBLCK if acquire else msvcrt.LK_UNLCK, 1)
        else:
            import fcntl

            fcntl.flock(
                handle.fileno(), (fcntl.LOCK_EX | fcntl.LOCK_NB) if acquire else fcntl.LOCK_UN
            )
    except OSError as exc:
        if acquire and exc.errno in {errno.EACCES, errno.EAGAIN, errno.EDEADLK}:
            return False
        raise
    return True


@contextmanager
def preparation_stage(
    stage: str, lifecycle: Any, cancel: Callable[[], bool] | None, *, gate: bool = True
) -> Iterator[None]:
    from datetime import UTC, datetime

    started = time.monotonic()
    runtime = {
        "stage": stage,
        "stage_started_at": datetime.now(UTC).isoformat(),
        "stage_elapsed_seconds": 0.0,
        "activity": "executing",
        "revision": 0,
    }
    lifecycle.emit("stage_start", runtime=runtime)
    try:
        if gate:
            with resource_slot("heavy", cancel=cancel, observe=lifecycle.emit):
                yield
        else:
            yield
    except Exception as exc:
        lifecycle.emit("preparation_error", stage=stage, error=str(exc))
        raise
    finally:
        lifecycle.emit(
            "stage_end",
            runtime={
                **runtime,
                "activity": "idle",
                "stage_elapsed_seconds": time.monotonic() - started,
            },
        )

src/codepilot/observability/runtime.py:
"""Canonical deterministic projection shared by event publication and API reads."""

from __future__ import annotations

from datetime import datetime
from typing import Any


def project_event(previous: dict[str, Any], event: dict[str, Any]) -> dict[str, Any]:
    runtime = dict(previous)
    seq = int(event.get("seq", 0))
    runtime["run_id"] = event.get("run_id")
    extra = event.get("extra") or {}
    facts = extra.get("facts") or {}
    hook = extra.get("hook")
    for suggestion in extra.get("suggestions", []):
        if suggestion.get("resource"):
            runtime["resource"] = suggestion["resource"]
    if hook in {"stage_start", "stage_end"}:
        incoming = facts.get("runtime") or {}
        if int(incoming.get("revision", 0)) < int(runtime.get("revision", 0)):
            return runtime
        runtime.update(incoming)
    if hook == "before_model":
        runtime["activity"] = "external_wait"
    if event.get("type") == "llm_call" or hook in {
        "after_model",
        "before_tool",
        "after_tool",
        "exploration",
    }:
        runtime["activity"] = "executing"
    if hook == "exploration" and (
        facts.get("new_relevant_evidence")
        or facts.get("hypothesis_changed")
        or facts.get("candidate_changed")
    ):
        runtime["last_effective_progress"] = event.get("timestamp")
    if hook in {"exploration", "candidate_changed"} and "has_modification" in facts:
        runtime["has_modification"] = facts["has_modification"]
    if hook == "candidate_changed":
        runtime["last_effective_progress"] = event.get("timestamp")
    if hook == "resource_wait":
        runtime["activity"] = "queued"
    if hook == "resource_acquired":
        runtime["activity"] = "executing"
        runtime["resource_queued_seconds"] = float(
            runtime.get("resource_queued_seconds", 0)
        ) + facts.get("queued_seconds", 0)
    if hook in {"task_start", "resume"}:
        runtime["policy_snapshot"] = facts.get("snapshot", {})
    if hook == "preparation_progress":
        runtime["preparation_progress"] = {
            "phase": facts.get("phase"),
            "counts": facts.get("counts"),
            "source": facts.get("source"),
        }
    if hook == "resume":
        runtime["recovery"] = {"reuse": facts.get("reuse"), "redo": facts.get("redo")}
    if hook == "contract_ready":
        runtime["contract"] = facts.get("contract")
    if hook == "after_validation":
        runtime["verification"] = facts.get("view")
        runtime["failure_summary"] = facts.get("failure_summary")
    if hook == "after_tool" and facts.get("cache"):
        runtime["last_cache"] = facts["cache"]
    if hook == "stage_end":
        runtime["activity"] = "idle"
    runtime["event_seq"] = max(seq, int(runtime.get("event_seq", 0)))
    return runtime


def activity_view(events: list[dict[str, Any]], *, now: datetime, terminal: bool) -> dict[str, Any]:
    runtime: dict[str, Any] = {}
    seen: set[int] = set()
    for event in sorted(events, key=lambda item: int(item.get("seq", 0))):
        seq = int(event.get("seq", 0))
        if seq and seq in seen:
            continue
        seen.add(seq)
        runtime["event_seq"] = max(seq, int(runtime.get("event_seq", 0)))
        projection = (event.get("extra") or {}).get("runtime_projection")
        if isinstance(projection, dict) and projection.get("run_id") == event.get("run_id"):
            runtime.update(projection)
        else:
            runtime = project_event(runtime, event)
    if terminal:
        runtime["activity"] = "finished"
    elif runtime.get("activity") != "idle" and runtime.get("stage_started_at"):
        try:
            start = datetime.fromisoformat(runtime["stage_started_at"])
            runtime["stage_elapsed_seconds"] = max(0, (now - start).total_seconds())
        except (ValueError, TypeError):
            pass
    return runtime

src/codepilot/rsi.py:
"""Offline, append-only improvement archives. No model, sandbox or network imports.

Only explicit selection changes future task advice. Historical results and costs
are never inputs to a write operation. Python code still uses worker/checkpoints.
"""

from __future__ import annotations

import argparse
import ast
import hashlib
import json
import os
import re
from pathlib import Path
from typing import Any

ROOT = Path(__file__).resolve().parents[2]
DEFAULT_ARCHIVE = ROOT / "configs" / "harness"
SOURCE_FILES = (
    "agents/coder.py",
    "agents/planner.py",
    "agents/reviewer.py",
    "agents/exploration.py",
    "tools/query_cache.py",
    "tools/read_tools.py",
    "observability/resources.py",
    "observability/runtime.py",
    "graph/deps.py",
    "graph/builder.py",
    "graph/checkpoint.py",
    "repo/index.py",
    "eval/assembly.py",
    "llm/tracking.py",
    "observability/lifecycle.py",
    "graph/evidence.py",
    "graph/harness.py",
    "tools/registry.py",
    "rsi.py",
)


def read_json(path: Path) -> dict[str, Any]:
    payload = json.loads(path.read_text(encoding="utf-8"))
    if not isinstance(payload, dict):
        raise ValueError(f"expected JSON object: {path}")
    return payload


def version_dir(root: Path, version: str) -> Path:
    if not re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9_.-]{0,99}", version) or ".." in version:
        raise ValueError("invalid version identifier")
    path = root.resolve() / "candidates" / version
    if not path.resolve().is_relative_to(root.resolve()):
        raise ValueError("archive path escapes root")
    return path


def snapshot_sources() -> dict[str, str]:
    base = Path(__file__).resolve().parent
    return {name: (base / name).read_text(encoding="utf-8") for name in SOURCE_FILES}


def extract_prompts(sources: dict[str, str]) -> dict[str, str]:
    prompts = {}
    for role in ("coder", "planner", "reviewer"):
        for node in ast.walk(ast.parse(sources[f"agents/{role}.py"])):
            if not isinstance(node, ast.Assign):
                continue
            if any(
                (isinstance(t, ast.Name) and t.id == "_SYSTEM")
                or (isinstance(t, ast.Attribute) and t.attr == "system_prompt")
                for t in node.targets
            ):
                try:
                    value = ast.literal_eval(node.value)
                except ValueError:
                    continue
                if isinstance(value, str):
                    prompts[role] = value
                    break
    return prompts


def validate_snapshot(snapshot: dict[str, Any], root: Path | None = None) -> dict[str, Any]:
    if snapshot.get("schema_version") != 1:
        raise ValueError("unsupported policy snapshot")
    if not isinstance(snapshot.get("instruction", ""), str):
        raise ValueError("instruction must be text")
    prompts = snapshot.get("prompts", {})
    if not isinstance(prompts, dict) or any(
        k not in {"coder", "planner", "reviewer"} or not isinstance(v, str)
        for k, v in prompts.items()
    ):
        raise ValueError("prompts must be versioned role text, not executable objects")
    entries = snapshot.get("experiences", [])
    if not isinstance(entries, list) or len(entries) > 100:
        raise ValueError("experiences must be a bounded list")
    required = {
        "id",
        "level",
        "source",
        "source_run",
        "applies_when",
        "invalid_when",
        "action",
        "version",
        "status",
        "evaluation_exposure",
    }
    for entry in entries:
        if not isinstance(entry, dict) or not required <= entry.keys():
            raise ValueError("experience provenance is incomplete")
        if entry["level"] not in {"L1", "L2", "L3"}:
            raise ValueError("L0 is task state; archived entries must be L1/L2/L3")
        if entry["evaluation_exposure"] != "public_only":
            raise ValueError("hidden-test/reference-patch experience is not injectable")
        if entry["level"] == "L3" and not entry.get("comparison_refs"):
            raise ValueError("L3 requires version comparison evidence")
        if entry["level"] == "L3":
            if root is None:
                raise ValueError("L3 comparison archive root required")
            for ref in entry["comparison_refs"]:
                if not isinstance(ref, str) or not re.fullmatch(r"[a-f0-9]{64}", ref):
                    raise ValueError("L3 comparison reference must be a content hash")
                comparison = read_json(root / "comparisons" / f"{ref}.json")
                if _json_hash(comparison) != ref:
                    raise ValueError("comparison identity mismatch")
                validate_comparison(root, comparison)
        if entry["status"] not in {"pending", "validated", "retired"}:
            raise ValueError("invalid experience status")
    return snapshot


def archive_root() -> Path:
    return Path(os.environ.get("CODEPILOT_HARNESS_ARCHIVE", str(DEFAULT_ARCHIVE))).resolve()


def load_selection(root: Path | None = None) -> dict[str, Any]:
    root = root if root is not None else archive_root()
    pointer = root / "active.json"
    if not pointer.exists():
        return {
            "schema_version": 1,
            "version": "builtin-phase26-v1",
            "parent": None,
            "status": "pending",
            "instruction": "",
            "experiences": [],
        }
    version = read_json(pointer)["version"]
    return validate_snapshot(read_json(version_dir(root, str(version)) / "snapshot.json"), root)


def selection_view(current: dict[str, Any]) -> dict[str, Any]:
    """Read-only configuration comparison; never applies the active pointer."""
    try:
        desired = load_selection()
        next_task = {"version": desired.get("version"), "status": desired.get("status", "pending")}
        return {
            "expected": next_task,
            "current_task": current,
            "next_task": next_task,
            "application": "new_tasks_only",
        }
    except (OSError, ValueError, KeyError) as exc:
        return {
            "current_task": current,
            "expected": None,
            "next_task": None,
            "application": "current_task_unchanged",
            "error": str(exc),
        }


def _condition(condition: Any, context: dict[str, Any]) -> bool | None:
    """Typed conjunction only. Unknown keys/values are not executable conditions."""
    if condition in (None, "", [], {}):
        return True
    if not isinstance(condition, dict):
        return None
    supported = {
        "repository",
        "stage",
        "failure_category",
        "runner",
        "environment",
        "version",
        "tags",
    }
    if not condition.keys() <= supported:
        return None
    for key, expected in condition.items():
        actual = context.get(key)
        if actual is None:
            return None
        if key == "tags":
            if not isinstance(expected, list) or not all(isinstance(v, str) for v in expected):
                return None
            if not set(expected) <= set(actual):
                return False
        elif isinstance(expected, str):
            if expected != "*" and actual != expected:
                return False
        elif isinstance(expected, list) and all(isinstance(v, str) for v in expected):
            if actual not in expected:
                return False
        else:
            return None
    return True


def retrieve(
    snapshot: dict[str, Any],
    repository: str,
    *,
    stage: str | None = None,
    failure_category: str | None = None,
    environment: dict[str, Any] | None = None,
    tags: tuple[str, ...] = (),
    audit: list[dict[str, Any]] | None = None,
    limit: int = 4,
    max_chars: int = 6000,
) -> list[dict[str, Any]]:
    """Rank advisory atomic entries; legacy prose is explicitly unevaluated."""
    context = {
        "repository": repository,
        "stage": stage,
        "failure_category": failure_category,
        "tags": tags,
        **(environment or {}),
    }
    decisions = audit if audit is not None else []
    eligible = []
    for entry in snapshot.get("experiences", []):
        reason = ""
        applicable = entry.get("applies_when")
        invalid = entry.get("invalid_when")
        invalid_match = _condition(invalid, context) if invalid else False
        legacy = isinstance(applicable, (str, list)) or isinstance(invalid, (str, list))
        if entry.get("status") == "retired":
            reason = "retired"
        elif entry.get("repository", "*") not in ("*", repository):
            reason = "repository_mismatch"
        elif entry.get("level") == "L1" and entry.get("repository", "*") == "*":
            reason = "L1_repository_required"
        elif invalid_match is True:
            reason = "invalid_when_matched"
        elif isinstance(invalid, dict) and invalid_match is None:
            reason = "invalid_when_unknown"
        elif isinstance(applicable, dict) and _condition(applicable, context) is not True:
            reason = "applies_when_unmet_or_unknown"
        if reason:
            decisions.append({"id": entry.get("id"), "decision": "rejected", "reason": reason})
            continue
        specificity = len(applicable) if isinstance(applicable, dict) else 0
        rank = (
            -specificity,
            entry.get("repository") != repository,
            entry.get("status") != "validated",
            not bool(entry.get("source_run")),
            str(entry.get("id", "")),
            str(entry.get("version", "")),
        )
        eligible.append(
            (
                rank,
                {
                    **entry,
                    "advisory": entry.get("status") != "validated" or legacy,
                    "conditions_evaluated": not legacy,
                    "condition_note": "legacy prose retained as explanation only"
                    if legacy
                    else "typed conditions",
                },
            )
        )
    chosen: list[dict[str, Any]] = []
    used = 0
    for _, entry in sorted(eligible, key=lambda pair: pair[0]):
        size = len(json.dumps(entry, ensure_ascii=False))
        reason = (
            "count_limit"
            if len(chosen) >= max(0, limit)
            else "context_limit"
            if used + size > max_chars
            else "matched"
        )
        decisions.append(
            {
                "id": entry["id"],
                "decision": "selected" if reason == "matched" else "truncated",
                "reason": reason,
            }
        )
        if reason == "matched":
            chosen.append(entry)
            used += size
    return chosen


def archive_candidate(root: Path, version: str, proposal: dict[str, Any]) -> Path:
    if not all(
        proposal.get(k)
        for k in ("hypothesis", "input_evidence", "candidate_changes", "code_revision")
    ):
        raise ValueError(
            "hypothesis, public evidence, candidate changes and code revision are required"
        )
    parent = proposal.get("parent")
    if parent:
        read_json(version_dir(root, str(parent)) / "snapshot.json")
    sources = snapshot_sources()
    snapshot = validate_snapshot(
        {
            "schema_version": 1,
            "version": version,
            "parent": parent,
            "status": "pending",
            "instruction": proposal.get("instruction", ""),
            "prompts": proposal.get("prompts", extract_prompts(sources)),
            "experiences": [{**e, "status": "pending"} for e in proposal.get("experiences", [])],
        },
        root,
    )
    folder = version_dir(root, version)
    folder.mkdir(parents=True, exist_ok=False)
    payload = {
        **proposal,
        "schema_version": 1,
        "version": version,
        "parent": parent,
        "status": "pending",
        "snapshot": snapshot,
        "source_hashes": {p: hashlib.sha256(t.encode()).hexdigest() for p, t in sources.items()},
        "source_snapshot": sources,
        "static_results": proposal.get("static_results", ["not checked"]),
        "future_metrics": proposal.get(
            "future_metrics", ["quality", "regressions", "time", "cost"]
        ),
        "effect_validation": "NOT_RUN",
        "auto_promote": False,
    }
    for name, content in (("snapshot.json", snapshot), ("candidate.json", payload)):
        (folder / name).write_text(
            json.dumps(content, ensure_ascii=False, indent=2) + "\n", encoding="utf-8"
        )
    return folder


def select(root: Path, version: str, *, allow_pending: bool = False) -> None:
    snapshot = validate_snapshot(read_json(version_dir(root, version) / "snapshot.json"), root)
    if snapshot.get("status") != "validated" and not allow_pending:
        raise ValueError(
            "pending candidate: explicit --allow-pending required; effects remain unverified"
        )
    root.mkdir(parents=True, exist_ok=True)
    target = root / "active.json"
    temporary = root / "active.next.json"
    temporary.write_text(
        json.dumps({"version": version, "new_tasks_only": True}) + "\n", encoding="utf-8"
    )
    temporary.replace(target)


def replay(path: Path, *, decisions: bool = False) -> list[dict[str, Any]]:
    from codepilot.agents.exploration import exploration_feedback

    records = []
    with path.open(encoding="utf-8") as handle:
        for line_no, line in enumerate(handle, 1):
            if not line.strip():
                continue
            try:
                event = json.loads(line)
                if not isinstance(event, dict):
                    raise ValueError("event is not an object")
            except (ValueError, TypeError) as exc:
                records.append({"line": line_no, "error": str(exc)})
                continue
            if decisions:
                extra = event.get("extra")
                if not isinstance(extra, dict) or extra.get("hook") != "exploration":
                    continue
                facts = extra.get("facts")
                if not isinstance(facts, dict):
                    records.append({"line": line_no, "error": "exploration facts unavailable"})
                    continue
                records.append(
                    {
                        "line": line_no,
                        "mode": "deterministic_decision",
                        "old_feedback": facts.get("feedback"),
                        "feedback": exploration_feedback(facts),
                        "effect_validation": "NOT_RUN",
                    }
                )
            else:
                records.append({"line": line_no, "mode": "trace", "event": event})
    return records


def _json_hash(value: dict[str, Any]) -> str:
    return hashlib.sha256(
        json.dumps(value, sort_keys=True, ensure_ascii=False).encode()
    ).hexdigest()


def validate_comparison(root: Path, comparison: dict[str, Any]) -> None:
    """Validate imported evidence identity and comparability, never invent effects."""
    import math

    if (
        comparison.get("schema_version") != 1
        or comparison.get("evaluation_exposure") != "public_only"
    ):
        raise ValueError("comparison schema/public provenance required")
    if comparison.get("decision") not in {"accept", "reject", "observe"}:
        raise ValueError("explicit comparison decision required")
    if not comparison.get("reason") or not comparison.get("evidence_refs"):
        raise ValueError("comparison reason and original evidence references required")
    references = comparison["evidence_refs"]
    if not isinstance(references, list):
        raise ValueError("evidence_refs must contain hashed local evidence")
    for reference in references:
        if not isinstance(reference, dict) or set(reference) != {"path", "sha256"}:
            raise ValueError("each evidence reference requires path and sha256")
        evidence = (root / str(reference["path"])).resolve(strict=True)
        if not evidence.is_relative_to(root.resolve()) or not evidence.is_file():
            raise ValueError("comparison evidence escapes archive")
        if hashlib.sha256(evidence.read_bytes()).hexdigest() != reference["sha256"]:
            raise ValueError("comparison original evidence changed")
    sides = [comparison.get("baseline"), comparison.get("candidate")]
    required_conditions = {
        "model",
        "provider",
        "budget_hash",
        "environment_hash",
        "success_definition_hash",
        "task_set_hash",
    }
    for side in sides:
        if not isinstance(side, dict):
            raise ValueError("baseline and candidate records required")
        snapshot = read_json(version_dir(root, side["version"]) / "snapshot.json")
        if side.get("snapshot_hash") != _json_hash(snapshot):
            raise ValueError("comparison snapshot identity mismatch")
        conditions = side.get("conditions", {})
        if set(conditions) != required_conditions or not all(
            isinstance(v, str) and v for v in conditions.values()
        ):
            raise ValueError("frozen comparison conditions required")
        if any(
            not re.fullmatch(r"[a-f0-9]{64}", conditions[key])
            for key in required_conditions
            if key.endswith("_hash")
        ):
            raise ValueError("comparison condition hashes must be SHA256")
        runs = side.get("runs")
        if (
            not isinstance(runs, list)
            or not runs
            or not all(isinstance(run, str) and run for run in runs)
            or len(set(runs)) != len(runs)
        ):
            raise ValueError("unique original run IDs required")
        metrics = side.get("metrics", {})
        if set(metrics) != {"quality", "regressions", "seconds", "cost", "tool_calls"}:
            raise ValueError("independent quality/time/cost metrics required")
        if any(
            isinstance(v, bool) or not isinstance(v, (int, float)) or not math.isfinite(v) or v < 0
            for v in metrics.values()
        ):
            raise ValueError("finite nonnegative observed metrics required")
        if side.get("cost_known") is not True:
            raise ValueError("known cost and source runs required")
    baseline = comparison["baseline"]
    candidate = comparison["candidate"]
    if (
        baseline["version"] == candidate["version"]
        or baseline["conditions"] != candidate["conditions"]
    ):
        raise ValueError("distinct versions under identical frozen conditions required")


def import_comparison(root: Path, comparison: dict[str, Any]) -> str:
    validate_comparison(root, comparison)
    identity = _json_hash(comparison)
    folder = root / "comparisons"
    folder.mkdir(parents=True, exist_ok=True)
    path = folder / f"{identity}.json"
    if not path.exists():
        with path.open("x", encoding="utf-8") as handle:
            handle.write(json.dumps(comparison, ensure_ascii=False, indent=2) + "\n")
    return identity


def promotion_readiness(root: Path, version: str, reference: str) -> dict[str, Any]:
    if not re.fullmatch(r"[a-f0-9]{64}", reference):
        raise ValueError("comparison hash required")
    comparison = read_json(root / "comparisons" / f"{reference}.json")
    if _json_hash(comparison) != reference:
        raise ValueError("comparison hash mismatch")
    validate_comparison(root, comparison)
    if comparison["candidate"]["version"] != version:
        raise ValueError("comparison belongs to another candidate")
    quality_floor = (
        comparison["candidate"]["metrics"]["quality"]
        >= comparison["baseline"]["metrics"]["quality"]
        and comparison["candidate"]["metrics"]["regressions"]
        <= comparison["baseline"]["metrics"]["regressions"]
    )
    return {
        "version": version,
        "comparison": reference,
        "eligible_for_manual_review": comparison["decision"] == "accept" and quality_floor,
        "quality_floor_met": quality_floor,
        "status": "pending",
        "auto_promote": False,
        "next_action": "Review original evidence and independent coverage before explicitly selecting; no source checkout is changed.",
    }


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--root", type=Path, default=DEFAULT_ARCHIVE)
    sub = parser.add_subparsers(dest="command", required=True)
    sub.add_parser("list")
    comparison_parser = sub.add_parser("import-comparison")
    comparison_parser.add_argument("path", type=Path)
    promotion = sub.add_parser("promotion-readiness")
    promotion.add_argument("version")
    promotion.add_argument("reference")
    for command in ("show", "select", "rollback"):
        item = sub.add_parser(command)
        item.add_argument("version")
        if command != "show":
            item.add_argument("--allow-pending", action="store_true")
    create = sub.add_parser("archive")
    create.add_argument("version")
    create.add_argument("--proposal", type=Path, required=True)
    trace = sub.add_parser("replay")
    trace.add_argument("path", type=Path)
    trace.add_argument("--mode", choices=("trace", "decision"), default="trace")
    args = parser.parse_args()
    if args.command == "list":
        result: Any = [
            p.parent.name for p in sorted((args.root / "candidates").glob("*/snapshot.json"))
        ]
    elif args.command == "import-comparison":
        result = import_comparison(args.root, read_json(args.path))
    elif args.command == "promotion-readiness":
        result = promotion_readiness(args.root, args.version, args.reference)
    elif args.command == "replay":
        result = replay(args.path, decisions=args.mode == "decision")
    elif args.command == "archive":
        result = str(archive_candidate(args.root, args.version, read_json(args.proposal)))
    elif args.command == "show":
        result = read_json(version_dir(args.root, args.version) / "candidate.json")
    else:
        version = args.version
        if args.command == "rollback":
            version = read_json(version_dir(args.root, version) / "snapshot.json").get("parent")
            if not version:
                raise ValueError("candidate has no archived parent")
        select(args.root, version, allow_pending=args.allow_pending)
        result = {"selected_for_new_tasks": version, "historical_results_unchanged": True}
    print(json.dumps(result, ensure_ascii=False, indent=2))


if __name__ == "__main__":
    main()

src/codepilot/tools/read_tools.py:
"""受控代码读取、ripgrep 搜索与索引 symbol 查询（P-07）。"""

from __future__ import annotations

import os
import re
import shutil
import subprocess
import time
from collections.abc import Iterator
from pathlib import Path, PurePosixPath, PureWindowsPath

from pydantic import BaseModel, ConfigDict, Field, field_validator

from codepilot.repo.index import RepositoryIndex
from codepilot.tools.base import Tool, ToolPermission, ToolResponse, WorkspacePathPolicy

__all__ = [
    "FindSymbolInput",
    "ReadFileInput",
    "SearchCodeInput",
    "find_symbol_tool",
    "read_file_tool",
    "search_code_tool",
]


class ReadFileInput(BaseModel):
    model_config = ConfigDict(extra="forbid")
    path: str
    start_line: int = Field(default=1, ge=1)
    end_line: int | None = Field(default=None, ge=1)


class SearchCodeInput(BaseModel):
    model_config = ConfigDict(extra="forbid")
    pattern: str = Field(min_length=1, max_length=1000)
    regex: bool = False
    path_glob: str | None = Field(default=None, max_length=500)

    @field_validator("path_glob")
    @classmethod
    def _safe_glob(cls, value: str | None) -> str | None:
        if value is None:
            return None
        normalized = value.replace("\\", "/")
        windows = PureWindowsPath(value)
        posix = PurePosixPath(normalized)
        if windows.is_absolute() or windows.anchor or posix.is_absolute() or ".." in posix.parts:
            raise ValueError("path_glob must remain inside the workspace")
        return normalized


class FindSymbolInput(BaseModel):
    model_config = ConfigDict(extra="forbid")
    name: str = Field(min_length=1, max_length=300)
    limit: int = Field(default=20, ge=1, le=50)


def read_file_tool(policy: WorkspacePathPolicy) -> Tool:
    def handle(raw: BaseModel) -> ToolResponse:
        args = ReadFileInput.model_validate(raw)
        path = policy.resolve(args.path, must_exist=True)
        policy.verify_identity(path)
        lines = path.read_text(encoding="utf-8").splitlines()
        if not lines and args.start_line == 1:
            return ToolResponse.success(
                "read_file",
                path=policy.relative(path),
                start_line=1,
                end_line=0,
                total_lines=0,
                content="",
            )
        end = args.end_line if args.end_line is not None else min(len(lines), args.start_line + 399)
        if end < args.start_line:
            return ToolResponse.failure(
                "read_file", "invalid_range", "end_line precedes start_line"
            )
        if end - args.start_line + 1 > 400:
            return ToolResponse.failure(
                "read_file", "range_too_large", "at most 400 lines may be read"
            )
        if args.start_line > max(1, len(lines)):
            return ToolResponse.failure(
                "read_file", "invalid_range", "start_line exceeds file length"
            )
        selected = lines[args.start_line - 1 : end]
        width = len(str(end))
        content = "\n".join(
            f"{number:>{width}} | {line}"
            for number, line in enumerate(selected, start=args.start_line)
        )
        return ToolResponse.success(
            "read_file",
            path=policy.relative(path),
            start_line=args.start_line,
            end_line=min(end, len(lines)),
            total_lines=len(lines),
            content=content,
        )

    return Tool(
        name="read_file",
        description="Read at most 400 numbered lines from a repository file.",
        permission=ToolPermission.READ,
        input_model=ReadFileInput,
        handler=handle,
    )


_MAX_SEARCH_MATCHES = 50
_MAX_SEARCH_FILE_BYTES = 5 * 1024 * 1024
_MAX_SEARCH_FILES = 20_000
_SEARCH_DEADLINE_SECONDS = 20.0
_RG_TIMEOUT_SECONDS = 15
_BINARY_PROBE_BYTES = 8192


def _is_denied_directory(relative: str, policy: WorkspacePathPolicy) -> bool:
    parts = relative.split("/")
    candidates = {"/".join(parts[:index]) for index in range(1, len(parts) + 1)}
    return any(rule in candidates for rule in policy.deny_directories)


def _search_root(policy: WorkspacePathPolicy, path_glob: str | None) -> Path:
    prefix = re.split(r"[?*\[]", path_glob or "", maxsplit=1)[0]
    directory = prefix.rsplit("/", 1)[0] if "/" in prefix else ""
    if directory:
        try:
            path = policy.resolve(directory, must_exist=True)
            if path.is_dir() and not (policy.root / directory).is_symlink():
                return path
        except (OSError, ValueError):
            pass
    return policy.root


def _iter_search_files(
    policy: WorkspacePathPolicy, path_glob: str | None
) -> Iterator[tuple[str, Path]]:
    """按确定顺序遍历 workspace 内可搜索文件（不跟随符号链接）。"""
    for dirpath, dirnames, filenames in os.walk(_search_root(policy, path_glob), followlinks=False):
        base = Path(dirpath)
        relative_dir = base.relative_to(policy.root).as_posix()
        kept: list[str] = []
        for name in sorted(dirnames):
            if (base / name).is_symlink():
                continue
            relative = name if relative_dir == "." else f"{relative_dir}/{name}"
            if _is_denied_directory(relative, policy):
                continue
            kept.append(name)
        dirnames[:] = kept
        for name in sorted(filenames):
            relative = name if relative_dir == "." else f"{relative_dir}/{name}"
            if path_glob is not None and not PurePosixPath(relative).match(path_glob):
                continue
            yield relative, base / name


def _search_with_python(
    policy: WorkspacePathPolicy,
    args: SearchCodeInput,
    *,
    fallback_reason: str,
    started: float | None = None,
) -> ToolResponse:
    """Bounded, policy-constrained fallback used when ripgrep is absent/slow.

    The fallback is not an unbounded replacement for rg: it has its own file
    count, file size, binary-content and total-time limits.  The diagnostics
    say which engine ran and why the accelerator was skipped, so a Planner
    timeout cannot be mistaken for a harness internal error.
    """
    stage = time.perf_counter() if started is None else started
    deadline = time.monotonic() + _SEARCH_DEADLINE_SECONDS
    pattern: re.Pattern[str] | None = re.compile(args.pattern) if args.regex else None
    matches: list[dict[str, str | int]] = []
    truncated = False
    fallback_timed_out = False
    scanned = 0
    for relative, path in _iter_search_files(policy, args.path_glob):
        if time.monotonic() > deadline:
            fallback_timed_out = True
            truncated = True
            break
        if scanned >= _MAX_SEARCH_FILES:
            truncated = True
            break
        if path.is_symlink():
            continue
        try:
            policy.resolve(relative, must_exist=True)
            data = path.read_bytes()
        except (OSError, ValueError):
            continue
        scanned += 1
        if len(data) > _MAX_SEARCH_FILE_BYTES:
            continue
        if b"\x00" in data[:_BINARY_PROBE_BYTES]:
            continue
        text = data.decode("utf-8", errors="replace")
        for line_no, line in enumerate(text.splitlines(), start=1):
            if pattern is not None:
                found = pattern.search(line)
                column = found.start() + 1 if found is not None else 0
            else:
                index = line.find(args.pattern)
                column = index + 1 if index >= 0 else 0
            if column == 0:
                continue
            matches.append(
                {
                    "path": relative,
                    "line": line_no,
                    "column": column,
                    "text": line[:1000],
                    "text_truncated": len(line) > 1000,
                }
            )
            if len(matches) > _MAX_SEARCH_MATCHES:
                truncated = True
                break
        if truncated:
            break
    matches.sort(key=lambda item: (str(item["path"]), int(item["line"]), int(item["column"])))
    return ToolResponse.success(
        "search_code",
        matches=matches[:_MAX_SEARCH_MATCHES],
        truncated=truncated,
        engine="python_fallback",
        fallback_reason=fallback_reason,
        fallback_timed_out=fallback_timed_out,
        files_scanned=scanned,
        max_files=_MAX_SEARCH_FILES,
        max_file_bytes=_MAX_SEARCH_FILE_BYTES,
        max_matches=_MAX_SEARCH_MATCHES,
        deadline_seconds=_SEARCH_DEADLINE_SECONDS,
        elapsed_ms=round((time.perf_counter() - stage) * 1000.0, 2),
    )


def _search_with_ripgrep(
    policy: WorkspacePathPolicy, args: SearchCodeInput, executable: str
) -> ToolResponse:
    command = [
        executable,
        "--line-number",
        "--column",
        "--no-heading",
        "--color=never",
        "--no-ignore-parent",
        "--no-ignore-global",
        "--no-config",
    ]
    if not args.regex:
        command.append("--fixed-strings")
    if args.path_glob:
        command.extend(["--glob", args.path_glob])
    for denied in sorted(policy.deny_directories):
        command.extend(["--glob", f"!{denied}/**"])
    scope = _search_root(policy, args.path_glob).relative_to(policy.root).as_posix()
    command.extend(["--", args.pattern, scope])
    started = time.perf_counter()
    try:
        completed = subprocess.run(
            command,
            cwd=policy.root,
            capture_output=True,
            text=True,
            encoding="utf-8",
            errors="replace",
            timeout=_RG_TIMEOUT_SECONDS,
            check=False,
        )
    except subprocess.TimeoutExpired:
        # Large repositories can exceed the external search timeout. Falling
        # back keeps an optional accelerator from turning into an internal error.
        return _search_with_python(policy, args, fallback_reason="rg_timeout", started=started)
    if completed.returncode not in (0, 1):
        return ToolResponse.failure(
            "search_code",
            "search_failed",
            completed.stderr.strip()[:1000] or "ripgrep failed",
            engine="ripgrep",
            exit_code=completed.returncode,
            stderr=completed.stderr.strip()[:1000],
            elapsed_ms=round((time.perf_counter() - started) * 1000.0, 2),
        )
    matches: list[dict[str, str | int]] = []
    for line in completed.stdout.splitlines():
        if len(matches) == _MAX_SEARCH_MATCHES:
            break
        match = re.match(r"^(.+?):(\d+):(\d+):(.*)$", line)
        if match is None:
            continue
        relative, line_no, column, text = match.groups()
        relative = relative.removeprefix(".\\").removeprefix("./").replace("\\", "/")
        try:
            policy.resolve(relative, must_exist=True)
        except ValueError:
            continue
        matches.append(
            {
                "path": relative,
                "line": int(line_no),
                "column": int(column),
                "text": text[:1000],
                "text_truncated": len(text) > 1000,
            }
        )
    matches.sort(key=lambda item: (str(item["path"]), int(item["line"]), int(item["column"])))
    return ToolResponse.success(
        "search_code",
        matches=matches,
        truncated=len(completed.stdout.splitlines()) > _MAX_SEARCH_MATCHES,
        engine="ripgrep",
        fallback_reason=None,
        fallback_timed_out=False,
        max_matches=_MAX_SEARCH_MATCHES,
        timeout_seconds=_RG_TIMEOUT_SECONDS,
        elapsed_ms=round((time.perf_counter() - started) * 1000.0, 2),
    )


def search_code_tool(policy: WorkspacePathPolicy) -> Tool:
    def handle(raw: BaseModel) -> ToolResponse:
        args = SearchCodeInput.model_validate(raw)
        if args.regex:
            try:
                re.compile(args.pattern)
            except re.error as exc:
                return ToolResponse.failure("search_code", "invalid_regex", str(exc))
        executable = shutil.which("rg")
        if executable is None:
            return _search_with_python(policy, args, fallback_reason="rg_missing")
        return _search_with_ripgrep(policy, args, executable)

    return Tool(
        name="search_code",
        description=(
            "Search repository text (ripgrep when available, built-in fallback) "
            "and return at most 50 matches."
        ),
        permission=ToolPermission.READ,
        input_model=SearchCodeInput,
        handler=handle,
    )


def find_symbol_tool(index: RepositoryIndex) -> Tool:
    def handle(raw: BaseModel) -> ToolResponse:
        args = FindSymbolInput.model_validate(raw)
        needle = args.name.casefold()
        found = []
        for symbol in index.symbol_objects():
            qname = symbol.qualified_name.casefold()
            name = symbol.name.casefold()
            if needle not in qname and needle not in name:
                continue
            basis = (
                "exact_qualified_name"
                if qname == needle
                else ("exact_name" if name == needle else "substring")
            )
            rank = {"exact_qualified_name": 0, "exact_name": 1, "substring": 2}[basis]
            found.append((rank, symbol.qualified_name, symbol.id, symbol, basis))
        found.sort(key=lambda item: item[:3])
        results = [
            {
                "symbol_id": item[3].id,
                "name": item[3].name,
                "qualified_name": item[3].qualified_name,
                "kind": item[3].kind,
                "path": item[3].path,
                "start_line": item[3].start_line,
                "end_line": item[3].end_line,
                "match_basis": item[4],
            }
            for item in found[: args.limit]
        ]
        return ToolResponse.success(
            "find_symbol", symbols=results, truncated=len(found) > args.limit
        )

    return Tool(
        name="find_symbol",
        description="Find indexed symbols by exact or substring match.",
        permission=ToolPermission.READ,
        input_model=FindSymbolInput,
        handler=handle,
    )


class ReadEvidenceInput(BaseModel):
    model_config = ConfigDict(extra="forbid")
    reference: str = Field(pattern=r"^tool-results/[a-f0-9]{64}\.json$")
    offset: int = Field(default=0, ge=0)
    length: int = Field(default=8000, ge=1, le=12000)


def read_evidence_tool(root: Path, policy: WorkspacePathPolicy) -> Tool:
    """Read immutable task-local result pages, never arbitrary artifact paths."""

    def handle(raw: BaseModel) -> ToolResponse:
        import json

        from codepilot.observability.lifecycle import snapshot_hash

        args = ReadEvidenceInput.model_validate(raw)
        path = (root / args.reference).resolve(strict=True)
        if not path.is_relative_to(root.resolve()) or path.stat().st_size > 16 * 1024 * 1024:
            raise ValueError("evidence reference is outside this task or too large")
        payload = json.loads(path.read_text(encoding="utf-8"))
        if snapshot_hash(payload) != path.stem:
            raise ValueError("evidence content identity mismatch")
        if payload.get("tool") not in {"read_file", "search_code"}:
            raise ValueError("only archived source queries are readable through this tool")
        data = payload.get("result", {}).get("data", {})
        paths = [data["path"]] if data.get("path") else []
        paths += [match["path"] for match in data.get("matches", [])]
        for relative in paths:
            policy.resolve(
                relative, must_exist=False
            )  # current permission rules still apply to historical data
        content = json.dumps(payload, ensure_ascii=False, indent=2)
        end = args.offset + args.length
        return ToolResponse.success(
            "read_evidence",
            content=content[args.offset : end],
            historical=True,
            reference=args.reference,
            next_offset=end if end < len(content) else None,
            truncated=end < len(content),
        )

    return Tool(
        name="read_evidence",
        description="Read a page of a previously returned task-local source evidence reference. Historical content is not current workspace state.",
        input_model=ReadEvidenceInput,
        permission=ToolPermission.READ,
        handler=handle,
    )

